// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // Fuzzed parameter is the array length and dummy addresses content; we pass an empty array scenario
    // The fuzzer will supply arbitrary addresses; we ensure we test the empty-array case by letting
    // an address array of length 0 be constructed from the fuzzed uint.
    function testFuzz_property(uint256 lenHint, address a0, address a1) public {
        // We must keep inputs wide. We'll construct an address[] of length derived from lenHint,
        // but the property we assert is about the empty-array case. Let the fuzzer explore inputs
        // and produce lenHint == 0 for the counterexample. We don't restrict lenHint.

        // Build _tos array according to lenHint but bounded to small sizes to avoid OOG in tests
        uint256 len = lenHint % 3; // produce array lengths 0,1,2
        address[] memory tos = new address[](len);
        if (len > 0) tos[0] = a0;
        if (len > 1) tos[1] = a1;

        // We will call transfer and observe whether it reverts or not.
        // According to the reference contract, when tos.length == 0 the call MUST revert due to require.
        // The mutant removes that require, so for tos.length == 0 it may succeed. We assert the reference
        // behavior: whenever tos.length == 0, transfer must revert (so ok == false). For non-empty arrays
        // the call may succeed; we don't assert about those.

        bool ok;
        try c.transfer(address(this), address(0xBEEF), tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // The single assertion: if we supplied an empty _tos array, the reference contract always reverts (ok == false).
        // The mutant that removed the require will allow ok == true for some inputs, causing this assertion to fail.
        if (len == 0) {
            assertTrue(!ok);
        } else {
            // For non-empty arrays we do not assert anything about success; still keep a tautological assertTrue(true)
            // is disallowed by rules, so we simply return and perform no assertion in that branch.
            return;
        }
    }
}
